-- ============================================================
-- URGENT FIX: Run This SQL in Supabase SQL Editor
-- ============================================================
-- Fixes:
-- 1. Error logging constraint (performance_issue, runtime_error, etc)
-- 2. Ensures all attendance features work properly
-- ============================================================

BEGIN;

-- ============================================
-- 1. FIX ERROR_LOGS TABLE CONSTRAINT
-- ============================================
DO $$
BEGIN
  -- Drop existing constraint if exists
    IF EXISTS (
        SELECT 1 FROM pg_constraint 
            WHERE conname = 'error_logs_error_type_check'
              ) THEN
                  ALTER TABLE error_logs DROP CONSTRAINT error_logs_error_type_check;
                      RAISE NOTICE '✅ Dropped old error_type constraint';
                        END IF;

                          -- Add new comprehensive constraint
                            ALTER TABLE error_logs ADD CONSTRAINT error_logs_error_type_check 
                              CHECK (error_type IN (
                                  'client_error',          -- Frontend errors
                                      'server_error',          -- Backend errors  
                                          'database_error',        -- DB query errors
                                              'api_error',             -- External API errors
                                                  'validation_error',      -- Data validation errors
                                                      'authentication_error',  -- Auth errors
                                                          'authorization_error',   -- Permission errors
                                                              'network_error',         -- Network/timeout errors
                                                                  'performance_issue',     -- Performance monitoring (NEW)
                                                                      '404_page',              -- 404 page not found (NEW)
                                                                          'runtime_error',         -- Runtime errors (NEW)
                                                                              'build_error',           -- Build errors (NEW)
                                                                                  'unknown_error'          -- Unclassified errors
                                                                                    ));
                                                                                      
                                                                                        RAISE NOTICE '✅ Added new error_type constraint with extended types';

                                                                                        EXCEPTION
                                                                                          WHEN undefined_table THEN
                                                                                              RAISE NOTICE '⚠️ error_logs table does not exist - skip constraint update';
                                                                                                WHEN OTHERS THEN
                                                                                                    RAISE NOTICE '⚠️ Error updating constraint: %', SQLERRM;
                                                                                                    END $$;

                                                                                                    -- Update column comment
                                                                                                    COMMENT ON COLUMN error_logs.error_type IS 'Type of error - supports all client/server error categories including performance monitoring';

                                                                                                    -- ============================================
                                                                                                    -- 2. CREATE INDEXES FOR PERFORMANCE (if not exist)
                                                                                                    -- ============================================
                                                                                                    DO $$
                                                                                                    BEGIN
                                                                                                      -- Create index for page_url if not exists
                                                                                                        IF NOT EXISTS (
                                                                                                            SELECT 1 FROM pg_indexes 
                                                                                                                WHERE indexname = 'idx_error_logs_page_url'
                                                                                                                  ) THEN
                                                                                                                      CREATE INDEX idx_error_logs_page_url ON error_logs(page_url);
                                                                                                                          RAISE NOTICE '✅ Created index: idx_error_logs_page_url';
                                                                                                                            END IF;

                                                                                                                              -- Create index for api_endpoint if not exists
                                                                                                                                IF NOT EXISTS (
                                                                                                                                    SELECT 1 FROM pg_indexes 
                                                                                                                                        WHERE indexname = 'idx_error_logs_api_endpoint'
                                                                                                                                          ) THEN
                                                                                                                                              CREATE INDEX idx_error_logs_api_endpoint ON error_logs(api_endpoint);
                                                                                                                                                  RAISE NOTICE '✅ Created index: idx_error_logs_api_endpoint';
                                                                                                                                                    END IF;

                                                                                                                                                      -- Create index for user_email if not exists
                                                                                                                                                        IF NOT EXISTS (
                                                                                                                                                            SELECT 1 FROM pg_indexes 
                                                                                                                                                                WHERE indexname = 'idx_error_logs_user_email'
                                                                                                                                                                  ) THEN
                                                                                                                                                                      CREATE INDEX idx_error_logs_user_email ON error_logs(user_email);
                                                                                                                                                                          RAISE NOTICE '✅ Created index: idx_error_logs_user_email';
                                                                                                                                                                            END IF;

                                                                                                                                                                              -- Create index for response_status if not exists
                                                                                                                                                                                IF NOT EXISTS (
                                                                                                                                                                                    SELECT 1 FROM pg_indexes 
                                                                                                                                                                                        WHERE indexname = 'idx_error_logs_response_status'
                                                                                                                                                                                          ) THEN
                                                                                                                                                                                              CREATE INDEX idx_error_logs_response_status ON error_logs(response_status);
                                                                                                                                                                                                  RAISE NOTICE '✅ Created index: idx_error_logs_response_status';
                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                    EXCEPTION
                                                                                                                                                                                                      WHEN undefined_table THEN
                                                                                                                                                                                                          RAISE NOTICE '⚠️ error_logs table does not exist - skip index creation';
                                                                                                                                                                                                            WHEN OTHERS THEN
                                                                                                                                                                                                                RAISE NOTICE '⚠️ Error creating indexes: %', SQLERRM;
                                                                                                                                                                                                                END $$;

                                                                                                                                                                                                                -- ============================================
                                                                                                                                                                                                                -- 3. VERIFY AI VERIFICATION LOGS TABLE
                                                                                                                                                                                                                -- ============================================
                                                                                                                                                                                                                DO $$
                                                                                                                                                                                                                BEGIN
                                                                                                                                                                                                                  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'ai_verification_logs') THEN
                                                                                                                                                                                                                      RAISE NOTICE '✅ ai_verification_logs table exists';
                                                                                                                                                                                                                          
                                                                                                                                                                                                                              -- Check if table has expected columns
                                                                                                                                                                                                                                  IF EXISTS (
                                                                                                                                                                                                                                        SELECT 1 FROM information_schema.columns 
                                                                                                                                                                                                                                              WHERE table_name = 'ai_verification_logs' AND column_name = 'reasoning'
                                                                                                                                                                                                                                                  ) THEN
                                                                                                                                                                                                                                                        RAISE NOTICE '✅ ai_verification_logs.reasoning column exists';
                                                                                                                                                                                                                                                            ELSE
                                                                                                                                                                                                                                                                  -- Add reasoning column if missing
                                                                                                                                                                                                                                                                        ALTER TABLE ai_verification_logs ADD COLUMN IF NOT EXISTS reasoning TEXT;
                                                                                                                                                                                                                                                                              RAISE NOTICE '✅ Added reasoning column to ai_verification_logs';
                                                                                                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                                                                                                    ELSE
                                                                                                                                                                                                                                                                                        RAISE NOTICE '⚠️ ai_verification_logs table does not exist';
                                                                                                                                                                                                                                                                                            RAISE NOTICE 'ℹ️ Run: create_ai_verification_logs_table.sql';
                                                                                                                                                                                                                                                                                              END IF;

                                                                                                                                                                                                                                                                                              EXCEPTION
                                                                                                                                                                                                                                                                                                WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                    RAISE NOTICE '⚠️ Error verifying ai_verification_logs: %', SQLERRM;
                                                                                                                                                                                                                                                                                                    END $$;

                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                    -- 4. VERIFY BIOMETRIC_DATA TABLE
                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                    DO $$
                                                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'biometric_data') THEN
                                                                                                                                                                                                                                                                                                          RAISE NOTICE '✅ biometric_data table exists';
                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                  -- Check for enrollment columns
                                                                                                                                                                                                                                                                                                                      IF EXISTS (
                                                                                                                                                                                                                                                                                                                            SELECT 1 FROM information_schema.columns 
                                                                                                                                                                                                                                                                                                                                  WHERE table_name = 'biometric_data' AND column_name = 'is_first_attendance_enrollment'
                                                                                                                                                                                                                                                                                                                                      ) THEN
                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '✅ biometric_data.is_first_attendance_enrollment column exists';
                                                                                                                                                                                                                                                                                                                                                ELSE
                                                                                                                                                                                                                                                                                                                                                      ALTER TABLE biometric_data ADD COLUMN IF NOT EXISTS is_first_attendance_enrollment BOOLEAN DEFAULT FALSE;
                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '✅ Added is_first_attendance_enrollment column';
                                                                                                                                                                                                                                                                                                                                                                END IF;
                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                        IF EXISTS (
                                                                                                                                                                                                                                                                                                                                                                              SELECT 1 FROM information_schema.columns 
                                                                                                                                                                                                                                                                                                                                                                                    WHERE table_name = 'biometric_data' AND column_name = 'enrollment_status'
                                                                                                                                                                                                                                                                                                                                                                                        ) THEN
                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '✅ biometric_data.enrollment_status column exists';
                                                                                                                                                                                                                                                                                                                                                                                                  ELSE
                                                                                                                                                                                                                                                                                                                                                                                                        ALTER TABLE biometric_data ADD COLUMN IF NOT EXISTS enrollment_status TEXT DEFAULT 'pending';
                                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '✅ Added enrollment_status column';
                                                                                                                                                                                                                                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                    ELSE
                                                                                                                                                                                                                                                                                                                                                                                                                        RAISE NOTICE '⚠️ biometric_data table does not exist';
                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE 'ℹ️ Table will be created on first attendance enrollment';
                                                                                                                                                                                                                                                                                                                                                                                                                              END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                              EXCEPTION
                                                                                                                                                                                                                                                                                                                                                                                                                                WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE NOTICE '⚠️ Error verifying biometric_data: %', SQLERRM;
                                                                                                                                                                                                                                                                                                                                                                                                                                    END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                    -- 5. VERIFY ATTENDANCE_RECORDS TABLE
                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                    DO $$
                                                                                                                                                                                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'attendance_records') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '✅ attendance_records table exists';
                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                  -- Verify metadata column exists and is JSONB
                                                                                                                                                                                                                                                                                                                                                                                                                                                      IF EXISTS (
                                                                                                                                                                                                                                                                                                                                                                                                                                                            SELECT 1 FROM information_schema.columns 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHERE table_name = 'attendance_records' 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          AND column_name = 'metadata' 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  AND data_type = 'jsonb'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '✅ attendance_records.metadata (jsonb) column exists';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ELSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      -- Add or convert to JSONB
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ALTER TABLE attendance_records ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  RAISE NOTICE '✅ Added/updated metadata column';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ELSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '⚠️ attendance_records table does not exist';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              EXCEPTION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE NOTICE '⚠️ Error verifying attendance_records: %', SQLERRM;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- 6. TEST ERROR LOGGING
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    DO $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    DECLARE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      test_id BIGINT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- Test insert with new error types
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          INSERT INTO error_logs (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  severity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      message,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          page_url,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              environment,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  metadata
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) VALUES 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ('performance_issue', 'medium', 'TEST: High CLS detected: 0.305', '/attendance', 'production', '{"test": true}'::jsonb),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ('runtime_error', 'low', 'TEST: Runtime error', '/dashboard', 'production', '{"test": true}'::jsonb),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ('404_page', 'low', 'TEST: Page not found', '/test-page', 'production', '{"test": true}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ON CONFLICT DO NOTHING
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RETURNING id INTO test_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        IF test_id IS NOT NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '✅ Test error logs inserted successfully (ID: %)', test_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Delete test records
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        DELETE FROM error_logs WHERE metadata->>'test' = 'true';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '✅ Test records cleaned up';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ELSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  RAISE NOTICE 'ℹ️ Test insert skipped (conflict or table issue)';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    EXCEPTION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      WHEN undefined_table THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '⚠️ error_logs table does not exist - skip test';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '⚠️ Error testing error logs: %', SQLERRM;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- 7. SUMMARY REPORT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DO $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DECLARE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error_count INT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ai_log_count INT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      attendance_count INT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        biometric_count INT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '=================================================';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '           SUMMARY REPORT';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '=================================================';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Count error logs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          SELECT COUNT(*) INTO error_count FROM error_logs WHERE deleted_at IS NULL;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '📊 Error Logs: % records', error_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                EXCEPTION WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE NOTICE '📊 Error Logs: Table not found or error';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- Count AI verification logs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                SELECT COUNT(*) INTO ai_log_count FROM ai_verification_logs;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE NOTICE '🤖 AI Verification Logs: % records', ai_log_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      EXCEPTION WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '🤖 AI Verification Logs: Table not found or error';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- Count attendance records
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      SELECT COUNT(*) INTO attendance_count FROM attendance_records;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '📋 Attendance Records: % records', attendance_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            EXCEPTION WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '📋 Attendance Records: Table not found or error';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      -- Count biometric data
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SELECT COUNT(*) INTO biometric_count FROM biometric_data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '🔐 Biometric Data: % enrollments', biometric_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  EXCEPTION WHEN OTHERS THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RAISE NOTICE '🔐 Biometric Data: Table not found or error';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '=================================================';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '✅ ALL FIXES APPLIED SUCCESSFULLY!';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  RAISE NOTICE '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE NOTICE '📋 Next Steps:';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RAISE NOTICE '1. Verify GEMINI_API_KEY in admin_settings table';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        RAISE NOTICE '2. Test attendance flow with real user';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE NOTICE '3. Monitor ai_verification_logs for accuracy';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RAISE NOTICE '4. Check error_logs for any new issues';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RAISE NOTICE '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RAISE NOTICE '=================================================';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                COMMIT;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- VERIFICATION QUERIES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ============================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- Check error_logs constraint
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                SELECT 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'error_logs constraint' as check_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    conname as constraint_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pg_get_constraintdef(oid) as definition
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      FROM pg_constraint 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      WHERE conname = 'error_logs_error_type_check';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      -- Check error_logs indexes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      SELECT 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'error_logs indexes' as check_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          indexname,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            indexdef
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FROM pg_indexes 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WHERE tablename = 'error_logs'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ORDER BY indexname;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Sample error log by type
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SELECT 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'error_logs by type' as check_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                error_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  COUNT(*) as count,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    MAX(created_at) as latest_occurrence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FROM error_logs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE deleted_at IS NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    GROUP BY error_type
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ORDER BY count DESC;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    